def check_conditions(M, x):
    if x[0] != 1:
        return False, "x0 is not 1"

    for i in range(1, M):
        lower_bound = 1 + (x[i]**3 - x[i]**2) / x[i-1]
        if x[i+1] < lower_bound:
            return False, f"x_{i+1} < lower bound at i={i}"

    total_sum = sum(x[i-1] / x[i] for i in range(1, M + 1))
    if abs(total_sum - 0.9375) > 1e-9:
        return False, f"Sum {total_sum} is not 0.9375"

    return True, "All conditions satisfied"

M = 4
x = [1, 2, 5, 134, 718240]
print(check_conditions(M, x))

def simple_search():
    solutions = []
    for M in range(1, 6):
        for x1 in range(2, 20):
            x2_min = max(1 + x1**2 * (x1 - 1), int(x1 / (0.9375 - 1/x1)) + 1)
            for x2 in range(x2_min, x2_min + 50):
                S2 = 1/x1 + x1/x2
                rem_sum = 0.9375 - S2
                if rem_sum <= 0: continue

                def solve(current_x, rem):
                    m_left = M - len(current_x)
                    if m_left == 1:
                        x_prev = current_x[-1]
                        if rem > 0:
                            x_curr = x_prev / rem
                            if abs(x_curr - round(x_curr)) < 1e-9:
                                x_curr_int = int(round(x_curr))
                                if x_curr_int >= 1 + (x_prev**3 - x_prev**2) / current_x[-2]:
                                    return [x_curr_int]
                        return []

                    x_prev = current_x[-1]
                    x_prev2 = current_x[-2]
                    x_i_min = max(1 + (x_prev**3 - x_prev**2) / x_prev2, int(x_prev / (rem - 1e-9)) + 1)
                    x_i_max = int(2 * x_prev / rem)

                    for x_i in range(x_i_min, x_i_max + 1):
                        res = solve(current_x + [x_i], rem - x_prev/x_i)
                        if res: return [x_i] + res
                    return []

                res = solve([1, x1, x2], rem_sum)
                if res:
                    solutions.append((M, [1] + [x1, x2] + res))
    return solutions

print(simple_search())

